// C5 T-03 — static structure of services/api/src/modules/lab/repository/*.repo.ts (no database needed).
// "Repositories (all tables)" (06 row T-03) + 02-TRD §3.1 "one file per table group; SQL only for schema `lab`; explicit tenant filter" + 05-SCHEMA §3.1 (no DELETE grant on any lab table).
// The table list is parsed from 05-SCHEMA §1 at test time, so a new table in the spec fails here until a repository touches it.
// lab.event_inbox is excluded: generated by C0 only (05-SCHEMA §1, C0 05-SCHEMA §3.9, 08 A30.2).
// Behaviour (tenant filter, versions, EXPLAIN) is in repository.integration.test.ts.
import { existsSync, readdirSync, readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';

const here = fileURLToPath(new URL('..', import.meta.url));                      // .../lab/repository/
const root = fileURLToPath(new URL('../../../../../../../', import.meta.url));
const REQUIRED_FILES = ['specimens.repo.ts', 'orders.repo.ts', 'orderTests.repo.ts', 'results.repo.ts', 'labSettings.repo.ts', 'barcodeCounters.repo.ts', 'deltaRules.repo.ts'];

const repoFiles = (): string[] => (existsSync(here) ? readdirSync(here).filter((f) => f.endsWith('.repo.ts')) : []);
const source = (f: string) => readFileSync(join(here, f), 'utf8');
const code = (s: string) => s.replace(/\/\*[\s\S]*?\*\//g, ' ').replace(/^\s*\/\/.*$/gm, ' ');

function specTables(): string[] {
  const md = readFileSync(join(root, 'spec', 'chunks', 'C5-lab-workflow', '05-SCHEMA.md'), 'utf8').replace(/\r\n?/g, '\n');
  const sec = md.slice(md.indexOf('## 1. Table inventory'), md.indexOf('## 2. Coded sets and seeds'));
  const rows = sec.split('\n').filter((l) => l.startsWith('| `lab.'));
  const names = rows.flatMap((l) => (l.split('|')[1] ?? '').match(/lab\.[a-z_]+/g) ?? []);
  return [...new Set(names)].filter((n) => n !== 'lab.event_inbox');
}

describe('T-03 repository files', () => {
  it('the spec lists the expected number of lab tables (25 single-table rows + 8 coded-set tables, minus event_inbox = 32)', () => {
    expect(specTables().length).toBe(32);
  });

  it.each(REQUIRED_FILES)('%s exists under repository/', (f) => {
    expect(repoFiles()).toContain(f);
  });

  it('every lab table of 05-SCHEMA §1 is read or written by some *.repo.ts', () => {
    const all = repoFiles().map((f) => code(source(f))).join('\n');
    const missing = specTables().filter((t) => !new RegExp(`\\b${t.replace('.', '\\.')}\\b`).test(all));
    expect(missing).toEqual([]);
  });

  it('SQL touches schema lab only (no FROM/JOIN/INTO/UPDATE on another schema or an unqualified table)', () => {
    for (const f of repoFiles()) {
      const bad = [...code(source(f)).matchAll(/\b(?:from|join|into|update)\s+(?!lab\.)([a-z_]+(?:\.[a-z_]+)?)\s*(?:\(|\s|$)/gi)]
        .map((m) => m[1]!).filter((t) => !['set', 'only', 'select'].includes(t.toLowerCase()) && /^[a-z_]+\.[a-z_]+$/.test(t));
      expect(bad, f).toEqual([]);
    }
  });

  it('no repository deletes rows (no DELETE grant on any lab table, 05-SCHEMA §3.1)', () => {
    for (const f of repoFiles()) expect(code(source(f)), f).not.toMatch(/\bdelete\s+from\b/i);
  });

  // Coarse by design (a regex cannot parse SQL strings); the per-statement proof is the recorded-statement and conflict tests in repository.integration.test.ts.
  it('each file with an UPDATE filters on tenant_id and bumps version (barcode counter: last_value + 1)', () => {
    for (const f of repoFiles()) {
      const c = code(source(f));
      const updates = (c.match(/\bUPDATE\s+lab\.\w+/gi) ?? []).length;
      if (updates === 0) continue;
      expect(c, f).toMatch(/tenant_id\s*=\s*\$/);
      if (f === 'barcodeCounters.repo.ts') { expect(c, f).toMatch(/last_value\s*=\s*(?:\w+\.)?last_value\s*\+\s*1/); continue; }
      expect((c.match(/\bversion\s*=\s*(?:\w+\.)?version\s*\+\s*1/g) ?? []).length, `${f}: version bump per UPDATE`).toBeGreaterThanOrEqual(updates);
    }
  });
});
